import { useState } from 'react';
import axios from 'axios';

export default function HomePage() {
  const [sentence, setSentence] = useState('');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleRecommend = async () => {
    try {
      setError('');
      const response = await axios.post('http://localhost:8000/api/recommend', { sentence });
      setResult(response.data);
    } catch (err) {
      setError('Recommendation failed.');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-6">
      <div className="max-w-3xl mx-auto bg-white shadow rounded-lg p-8">
        <h1 className="text-3xl font-semibold mb-4">Marathi Proverb Recommendation</h1>
        <p className="text-slate-600 mb-6">Type a Marathi sentence and get the most relevant proverb.</p>
        <textarea
          className="w-full border rounded p-3 mb-4"
          value={sentence}
          onChange={e => setSentence(e.target.value)}
          rows={4}
          placeholder="तो अभ्यास न करता परीक्षेला गेला..."
        />
        <button
          className="bg-blue-600 text-white px-5 py-2 rounded"
          onClick={handleRecommend}
        >
          Recommend Proverb
        </button>
        {error && <p className="mt-4 text-red-600">{error}</p>}
        {result && (
          <div className="mt-6 bg-sky-50 p-4 rounded">
            <h2 className="text-xl font-semibold">Recommended Proverb</h2>
            <p className="mt-2"><strong>Proverb:</strong> {result.proverb}</p>
            <p className="mt-2"><strong>Meaning:</strong> {result.meaning}</p>
            <p className="mt-2"><strong>Category:</strong> {result.category}</p>
            <p className="mt-2"><strong>Emotion:</strong> {result.emotion}</p>
            <p className="mt-2"><strong>Confidence:</strong> {result.confidence}%</p>
          </div>
        )}
      </div>
    </div>
  );
}
